package com.kaymlyn.planeteater.claude;

import com.kaymlyn.planeteater.simulation.physics.Orbit;
import com.kaymlyn.planeteater.simulation.physics.PhysicsConstants;
import com.kaymlyn.planeteater.simulation.physics.Vector3D;
import com.kaymlyn.planeteater.simulation.vehicles.Spacecraft;
import lombok.Getter;
import lombok.AllArgsConstructor;

/**
 * Plans and executes multi-burn orbital transfers
 * Breaks down complex transfers into multiple maneuver legs
 *
 * Generated by Claude (Sonnet 4.5)
 */
public class MultiBurnTransfer {

    /**
     * Represents a single burn maneuver in the transfer
     */
    @Getter
    @AllArgsConstructor
    public static class BurnManeuver {
        private String name;                    // Description of this burn
        private Vector3D position;              // Position where burn occurs
        private Vector3D velocityBefore;        // Velocity before burn
        private Vector3D velocityAfter;         // Velocity after burn
        private double deltaV;                  // Delta-v magnitude (m/s)
        private Vector3D deltaVVector;          // Delta-v as vector
        private double fuelRequired;            // Fuel needed for this burn (kg)
        private double burnDuration;            // Time to complete burn (seconds)
        private double timeFromStart;           // Time from transfer start (seconds)

        @Override
        public String toString() {
            return String.format("Burn[%s: Δv=%.1f m/s, fuel=%.1f kg, t=+%.2f days]",
                    name, deltaV, fuelRequired, timeFromStart / PhysicsConstants.SECONDS_PER_DAY);
        }
    }

    /**
     * Represents a coast phase between burns
     */
    @Getter
    @AllArgsConstructor
    public static class CoastPhase {
        private String description;             // What's happening during coast
        private Vector3D startPosition;         // Position at coast start
        private Vector3D endPosition;           // Position at coast end
        private Orbit orbit;         // Orbital elements during coast
        private double duration;                // Coast duration (seconds)
        private double startTime;               // Time from transfer start (seconds)

        @Override
        public String toString() {
            return String.format("Coast[%s: %.2f days, a=%.3e m, e=%.3f]",
                    description, duration / PhysicsConstants.SECONDS_PER_DAY,
                    orbit.semiMajorAxis(), orbit.eccentricity());
        }
    }

    /**
     * Calculate a multi-burn transfer between arbitrary orbits
     * Automatically determines the optimal number and timing of burns
     * Includes wait times to reach optimal burn locations
     *
     * @param startOrbit Starting orbital elements
     * @param targetOrbit Target orbital elements
     * @param centralMass Mass of central body (kg)
     * @param spacecraft Spacecraft performing transfer
     * @return Complete transfer plan with all burns and coasts
     */
    public static TransferPlan calculateMultiBurnTransfer(Orbit startOrbit,
                                                          Orbit targetOrbit,
                                                          double centralMass,
                                                          Spacecraft spacecraft) {
        TransferPlan plan = new TransferPlan(startOrbit, targetOrbit);
        double mu = PhysicsConstants.G * centralMass;

        // Extract orbital parameters
        double a1 = startOrbit.semiMajorAxis();
        double e1 = startOrbit.eccentricity();
        double i1 = startOrbit.inclination();

        double a2 = targetOrbit.semiMajorAxis();
        double e2 = targetOrbit.eccentricity();
        double i2 = targetOrbit.inclination();

        double inclinationChange = Math.abs(i2 - i1);

        // Get orbital points for timing calculations
        OrbitalPoints points = OrbitalPoints.calculateOrbitalPoints(startOrbit);

        // Determine transfer strategy based on orbit characteristics
        double currentTime = 0.0;
        Orbit currentOrbit = startOrbit;

        // STEP 1: Change inclination if needed (most efficient at apoapsis)
        if (inclinationChange > Math.toRadians(0.1)) { // More than 0.1 degrees

            // Wait until we reach apoapsis
            double waitTime = startOrbit.calculateTimeToPoint(startOrbit.apoapsisPoint());
            plan.setTotalDuration(plan.getTotalWaitTime() + waitTime);

            if (waitTime > 0) {
                CoastPhase waitCoast = new CoastPhase(
                        "Coast to apoapsis for inclination change",
                        startOrbit.semiMinorPositive(),
                        startOrbit.apoapsisPoint(),
                        startOrbit,
                        waitTime, currentTime
                );
                plan.addCoast(waitCoast);
                currentTime += waitTime;
            }

            // Burn 1: Inclination change at apoapsis
//            double r_apo = a1 * (1 + e1); //validate value matches magnitude of apoapsisPoint
            double v_apo = Math.sqrt(mu * (2.0/startOrbit.apoapsisPoint().magnitude() - 1.0/startOrbit.semiMajorAxis())); //validate correct

            double inclinationDeltaV = 2.0 * v_apo * Math.sin(inclinationChange / 2.0);

            Vector3D position = startOrbit.apoapsisPoint();
            //I think these need to be rotated into 3 space?
            Vector3D velBefore = new Vector3D(0, v_apo, 0);
            Vector3D deltaVVec = new Vector3D(0, 0, inclinationDeltaV);
            Vector3D velAfter = velBefore.add(deltaVVec);

            double fuel = spacecraft.fuelRequired(inclinationDeltaV);

            BurnManeuver inclinationBurn = new BurnManeuver(
                    "Inclination Change at Apoapsis",
                    position, velBefore, velAfter,
                    inclinationDeltaV, deltaVVec, fuel,
                    60.0,
                    currentTime
            );
            plan.addBurn(inclinationBurn);

            // Coast to next maneuver point
            double coastTime = startOrbit.orbitalPeriod()/2; // Half orbit
            CoastPhase coast1 = new CoastPhase(
                    "Coast after inclination change",
                    position, position,
                    new Orbit(a1, e1, i2,
                            startOrbit.ascendingNode(), startOrbit.periapsis(), Math.PI, startOrbit.centerBody(), 0.0),
                    coastTime, currentTime
            );
            plan.addCoast(coast1);
            currentTime += coastTime;

            // Update current orbit with new inclination
            currentOrbit = new Orbit(a1, e1, i2,
                    startOrbit.ascendingNode(), startOrbit.periapsis(), 0, startOrbit.centerBody(), 0.0);

            // Recalculate points for the new orbit
            points = OrbitalPoints.calculateOrbitalPoints(currentOrbit);
        }

        // STEP 2: Hohmann-like transfer to change semi-major axis and eccentricity

        // Wait until we reach periapsis for departure burn (most efficient)
        double waitToPeriapsis = OrbitalPoints.calculateTimeToPeriapsis(currentOrbit, centralMass);
        if (waitToPeriapsis > 0) {
            plan.setTotalWaitTime(plan.getTotalWaitTime() + waitToPeriapsis);
            CoastPhase waitCoast = new CoastPhase(
                    "Coast to periapsis for transfer",
                    currentOrbit.semiMajorAxis() * (1 + currentOrbit.eccentricity()) >
                            currentOrbit.semiMajorAxis() * (1 - currentOrbit.eccentricity()) ?
                            points.getApoapsis() : points.getPeriapsis(),
                    points.getPeriapsis(),
                    currentOrbit,
                    waitToPeriapsis, currentTime
            );
            plan.addCoast(waitCoast);
            currentTime += waitToPeriapsis;
        }

        // Determine if we need intermediate orbits for large transfers
        double radiusRatio = Math.max(a2, a1) / Math.min(a2, a1);
        boolean needsMultipleTransfers = radiusRatio > 10.0;

        if (needsMultipleTransfers) {
            // Bi-elliptic transfer for efficiency
            plan = calculateBiEllipticTransfer(startOrbit, targetOrbit, centralMass,
                    spacecraft, plan, currentTime);
        } else {
            // Standard Hohmann transfer

            // Burn 2: Departure burn (raise/lower apoapsis)
            double r1 = a1 * (1 - e1); // At periapsis
            double v1 = Math.sqrt(mu * (2.0/r1 - 1.0/a1));

            // Transfer orbit semi-major axis
            double a_transfer = (r1 + a2) / 2.0;
            double v_transfer_peri = Math.sqrt(mu * (2.0/r1 - 1.0/a_transfer));

            double departureDeltaV = Math.abs(v_transfer_peri - v1);

            Vector3D departurePos = points.getPeriapsis();
            Vector3D departureBefore = new Vector3D(0, v1, 0);
            Vector3D departureDelta = new Vector3D(0, departureDeltaV, 0);
            Vector3D departureAfter = departureBefore.add(departureDelta);

            double departureFuel = spacecraft.fuelRequired(departureDeltaV);

            BurnManeuver departureBurn = new BurnManeuver(
                    "Transfer Injection at Periapsis",
                    departurePos, departureBefore, departureAfter,
                    departureDeltaV, departureDelta, departureFuel,
                    60.0, currentTime
            );
            plan.addBurn(departureBurn);

            // Coast on transfer orbit
            double transferTime = Math.PI * Math.sqrt(Math.pow(a_transfer, 3) / mu);
            CoastPhase transferCoast = new CoastPhase(
                    "Transfer orbit coast",
                    departurePos, new Vector3D(a2, 0, 0),
                    new Orbit(a_transfer, Math.abs(a2 - r1)/(a2 + r1), i2, 0, 0, 0, startOrbit.centerBody(), 0.0),
                    transferTime, currentTime
            );
            plan.addCoast(transferCoast);
            currentTime += transferTime;

            // Burn 3: Circularization at target altitude
            double r2 = a2;
            double v_transfer_apo = Math.sqrt(mu * (2.0/r2 - 1.0/a_transfer));
            double v2 = Math.sqrt(mu / r2); // Circular orbit velocity

            double circularizationDeltaV = Math.abs(v2 - v_transfer_apo);

            Vector3D circPos = new Vector3D(r2, 0, 0);
            Vector3D circBefore = new Vector3D(0, v_transfer_apo, 0);
            Vector3D circDelta = new Vector3D(0, circularizationDeltaV, 0);
            Vector3D circAfter = new Vector3D(0, v2, 0);

            double circFuel = spacecraft.fuelRequired(circularizationDeltaV);

            BurnManeuver circularizationBurn = new BurnManeuver(
                    "Circularization at Target",
                    circPos, circBefore, circAfter,
                    circularizationDeltaV, circDelta, circFuel,
                    60.0, currentTime
            );
            plan.addBurn(circularizationBurn);
        }

        // STEP 3: Adjust eccentricity if needed
        if (Math.abs(e2 - 0) > 0.01 && !needsMultipleTransfers) {
            double eccentricityDeltaV = Math.abs(e2 - 0) * Math.sqrt(mu / a2) * 0.5;

            Vector3D eccPos = new Vector3D(a2, 0, 0);
            Vector3D eccBefore = new Vector3D(0, Math.sqrt(mu / a2), 0);
            Vector3D eccDelta = new Vector3D(0, eccentricityDeltaV, 0);
            Vector3D eccAfter = eccBefore.add(eccDelta);

            double eccFuel = spacecraft.fuelRequired(eccentricityDeltaV);

            BurnManeuver eccentricityBurn = new BurnManeuver(
                    "Eccentricity Adjustment",
                    eccPos, eccBefore, eccAfter,
                    eccentricityDeltaV, eccDelta, eccFuel,
                    60.0, currentTime
            );
            plan.addBurn(eccentricityBurn);
        }

        // Check feasibility
        plan.setTotalDuration(currentTime);
        if (plan.getTotalFuelRequired() > spacecraft.getFuelMass()) {
            plan.setInfeasible("Insufficient fuel: need " + plan.getTotalFuelRequired() +
                    " kg, have " + spacecraft.getFuelMass() + " kg");
        }
        if (plan.getTotalDeltaV() > spacecraft.getAvailableDeltaV()) {
            plan.setInfeasible("Insufficient delta-v capability");
        }

        return plan;
    }

    /**
     * Calculate a bi-elliptic transfer (more efficient for large radius changes)
     */
    private static TransferPlan calculateBiEllipticTransfer(Orbit startOrbit,
                                                            Orbit targetOrbit,
                                                            double centralMass,
                                                            Spacecraft spacecraft,
                                                            TransferPlan plan,
                                                            double startTime) {
        double mu = PhysicsConstants.G * centralMass;
        double a1 = startOrbit.semiMajorAxis();
        double a2 = targetOrbit.semiMajorAxis();

        // Use intermediate orbit at ~1.5x the larger radius
        double r_intermediate = Math.max(a1, a2) * 1.5;

        double currentTime = startTime;

        // Burn 1: Raise apoapsis to intermediate orbit
        double r1 = a1;
        double v1 = Math.sqrt(mu / r1);
        double a_transfer1 = (r1 + r_intermediate) / 2.0;
        double v_transfer1 = Math.sqrt(mu * (2.0/r1 - 1.0/a_transfer1));
        double dv1 = Math.abs(v_transfer1 - v1);

        plan.addBurn(new BurnManeuver("Bi-elliptic: First burn",
                new Vector3D(r1, 0, 0), new Vector3D(0, v1, 0),
                new Vector3D(0, v_transfer1, 0), dv1, new Vector3D(0, dv1, 0),
                spacecraft.fuelRequired(dv1), 60.0, currentTime));

        double coast1Time = Math.PI * Math.sqrt(Math.pow(a_transfer1, 3) / mu);
        plan.addCoast(new CoastPhase("Bi-elliptic: Coast to apoapsis",
                new Vector3D(r1, 0, 0), new Vector3D(r_intermediate, 0, 0),
                new Orbit(a_transfer1, (r_intermediate - r1)/(r_intermediate + r1),
                        startOrbit.inclination(), 0, 0, 0, startOrbit.centerBody(), 0.0),
                coast1Time, currentTime));
        currentTime += coast1Time;

        // Burn 2: At intermediate apoapsis, adjust for final orbit
        double v_int = Math.sqrt(mu * (2.0/r_intermediate - 1.0/a_transfer1));
        double a_transfer2 = (r_intermediate + a2) / 2.0;
        double v_transfer2 = Math.sqrt(mu * (2.0/r_intermediate - 1.0/a_transfer2));
        double dv2 = Math.abs(v_transfer2 - v_int);

        plan.addBurn(new BurnManeuver("Bi-elliptic: Second burn",
                new Vector3D(r_intermediate, 0, 0), new Vector3D(0, v_int, 0),
                new Vector3D(0, v_transfer2, 0), dv2, new Vector3D(0, dv2, 0),
                spacecraft.fuelRequired(dv2), 60.0, currentTime));

        double coast2Time = Math.PI * Math.sqrt(Math.pow(a_transfer2, 3) / mu);
        plan.addCoast(new CoastPhase("Bi-elliptic: Coast to target",
                new Vector3D(r_intermediate, 0, 0), new Vector3D(a2, 0, 0),
                new Orbit(a_transfer2, Math.abs(a2 - r_intermediate)/(a2 + r_intermediate),
                        startOrbit.inclination(), 0, 0, 0, startOrbit.centerBody(), 0.0),
                coast2Time, currentTime));
        currentTime += coast2Time;

        // Burn 3: Circularize at target
        double v_arrival = Math.sqrt(mu * (2.0/a2 - 1.0/a_transfer2));
        double v_target = Math.sqrt(mu / a2);
        double dv3 = Math.abs(v_target - v_arrival);

        plan.addBurn(new BurnManeuver("Bi-elliptic: Circularization",
                new Vector3D(a2, 0, 0), new Vector3D(0, v_arrival, 0),
                new Vector3D(0, v_target, 0), dv3, new Vector3D(0, dv3, 0),
                spacecraft.fuelRequired(dv3), 60.0, currentTime));

        return plan;
    }
}
